SELECT tv.*
FROM PERF_TARGET_VALUE tv
JOIN PERF_TARGET_PLAN tp ON tv.plan_id = tp.id
WHERE tp.status = 'ACTIVE'
  AND tv.subject_type = #{subjectType}
  AND tv.subject_id = #{subjectId}
  AND tv.metric_code = #{metricCode}
  AND tv.start_date <= #{dataDate}
  AND tv.end_date >= #{dataDate}
LIMIT 1

SELECT DISTINCT tv.subject_id
FROM PERF_TARGET_VALUE tv
JOIN PERF_TARGET_PLAN tp ON tv.plan_id = tp.id
WHERE tp.status = 'ACTIVE'
  AND tv.subject_type = 'EMP'
  AND tv.start_date <= #{dataDate}
  AND tv.end_date >= #{dataDate}
  AND tv.metric_code IN
  #{mc}

